-- KinSpace D1 seed: conditions + treatments knowledge base
-- + clinically-grounded evidence baseline (effectiveness, symptom/trigger/test prevalence).
-- Re-runnable: every insert is INSERT OR IGNORE / upsert-safe.

INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('depression', 'Depression', '["Major Depressive Disorder","MDD"]', 'Persistent low mood, loss of interest, fatigue, sleep/appetite changes. One of the most common mental-health conditions worldwide.', 'mental', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('anxiety', 'Generalised Anxiety', '["GAD","Anxiety Disorder"]', 'Excessive, hard-to-control worry plus physical symptoms like tension, restlessness, and sleep trouble.', 'mental', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('ptsd', 'PTSD', '["Post-Traumatic Stress Disorder"]', 'Trauma-driven re-experiencing, avoidance, hypervigilance, and mood symptoms after a distressing event.', 'mental', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('cptsd', 'Complex PTSD', '["C-PTSD"]', 'PTSD plus difficulties with emotion regulation, self-concept, and relationships after prolonged or repeated trauma.', 'mental', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('adhd', 'ADHD', '["Attention Deficit Hyperactivity Disorder"]', 'Differences in attention regulation, impulse control, and executive function across the lifespan.', 'mental', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('autism', 'Autism', '["ASD","Autism Spectrum"]', 'Neurodivergent pattern affecting communication, sensory processing, and social experience.', 'neurological', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('bipolar', 'Bipolar Disorder', '["BP1","BP2"]', 'Mood episodes ranging from depression to mania or hypomania, often with stable periods in between.', 'mental', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('ocd', 'OCD', '["Obsessive-Compulsive Disorder"]', 'Intrusive, distressing thoughts (obsessions) and repeated behaviors or mental acts (compulsions) aimed at reducing them.', 'mental', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('bpd', 'BPD', '["Borderline Personality Disorder","EUPD"]', 'Intense emotion shifts, unstable self-image, difficult relationship patterns, often rooted in early attachment experiences.', 'mental', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('fibromyalgia', 'Fibromyalgia', '["Fibro","FM"]', 'Widespread pain, fatigue, sleep disturbance, and cognitive fog without an inflammatory cause on standard tests.', 'pain', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('chronic-pain', 'Chronic Pain', '["Persistent Pain"]', 'Pain lasting longer than three months, often multi-system and requiring a combination of approaches.', 'pain', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('me-cfs', 'ME/CFS', '["Myalgic Encephalomyelitis","Chronic Fatigue Syndrome"]', 'Debilitating fatigue, post-exertional malaise, unrefreshing sleep, and cognitive dysfunction.', 'chronic', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('long-covid', 'Long COVID', '["Post-acute Sequelae of COVID-19","PASC"]', 'Multi-system symptoms persisting weeks-to-years after COVID-19 infection.', 'chronic', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('migraine', 'Migraine', '["Chronic Migraine"]', 'Recurrent neurological attacks with severe headache, often with nausea, light/sound sensitivity, and sometimes aura.', 'neurological', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('endometriosis', 'Endometriosis', '["Endo"]', 'Tissue similar to the uterine lining grows outside the uterus, causing pain, inflammation, and often fertility impacts.', 'chronic', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('ibs', 'IBS', '["Irritable Bowel Syndrome"]', 'Functional digestive disorder with abdominal pain and altered bowel habits, often trigger-sensitive.', 'chronic', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('crohns', 'Crohn''s Disease', '["Crohns","IBD - Crohn"]', 'Chronic inflammation anywhere in the digestive tract, typically patchy and transmural.', 'autoimmune', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('ulcerative-colitis', 'Ulcerative Colitis', '["UC","IBD - UC"]', 'Chronic inflammation of the colon and rectum, usually continuous and mucosal.', 'autoimmune', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('hashimotos', 'Hashimoto''s', '["Autoimmune Thyroiditis"]', 'Autoimmune attack on the thyroid, often leading to hypothyroidism with fatigue, weight changes, and cognitive slowing.', 'autoimmune', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('type-1-diabetes', 'Type 1 Diabetes', '["T1D"]', 'Autoimmune destruction of insulin-producing cells. Lifelong insulin replacement required.', 'autoimmune', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('type-2-diabetes', 'Type 2 Diabetes', '["T2D"]', 'Insulin resistance and relative insulin deficiency affecting blood glucose regulation.', 'metabolic', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('celiac', 'Celiac Disease', '["Coeliac"]', 'Autoimmune reaction to gluten that damages the small intestine. Treated primarily through strict gluten-free diet.', 'autoimmune', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('pots', 'POTS', '["Postural Orthostatic Tachycardia Syndrome"]', 'Abnormal heart-rate response to standing with dizziness, fatigue, and brain fog.', 'chronic', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('eds', 'Ehlers-Danlos', '["EDS","hEDS"]', 'Group of connective tissue disorders affecting joints, skin, and other tissues. Hypermobile type is most common.', 'chronic', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('hypothyroidism', 'Hypothyroidism', '["Underactive Thyroid"]', 'Low thyroid hormone production causing fatigue, weight gain, cold intolerance, and mood symptoms.', 'metabolic', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('insomnia', 'Insomnia', '["Chronic Insomnia"]', 'Difficulty falling asleep, staying asleep, or waking refreshed despite adequate opportunity.', 'sleep', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('sad', 'Seasonal Depression', '["SAD","Seasonal Affective Disorder"]', 'Depressive symptoms that follow a seasonal pattern, commonly in fall/winter, often helped by light therapy.', 'mental', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('chronic-lyme', 'Chronic Lyme', '["Post-treatment Lyme Disease Syndrome","PTLDS"]', 'Persistent multi-system symptoms following Lyme infection, including fatigue, joint pain, and cognitive issues.', 'chronic', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('panic-disorder', 'Panic Disorder', '["Panic Attacks"]', 'Recurrent, unexpected panic attacks plus worry about future attacks and behavior changes to avoid them.', 'mental', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('social-anxiety', 'Social Anxiety', '["Social Phobia"]', 'Significant fear of social situations and being judged, leading to avoidance that interferes with life.', 'mental', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('hiv', 'HIV', '["HIV/AIDS","Human Immunodeficiency Virus"]', 'HIV is a virus that gradually weakens the immune system, but it is now a manageable lifelong condition, not a death sentence. With daily antiretroviral therapy taken consistently, people live long, healthy lives and the virus becomes undetectable and untransmittable to others (U=U).', 'infectious', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('tuberculosis', 'Tuberculosis', '["TB","Pulmonary TB"]', 'Tuberculosis is a bacterial infection, usually of the lungs, caused by Mycobacterium tuberculosis and spread through the air when someone coughs. The good news is that it is curable: a full course of TB antibiotics taken every day for the whole treatment period clears the infection, and finishing every dose is what stops the disease from coming back or becoming drug-resistant.', 'infectious', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('hypertension', 'Hypertension', '["High Blood Pressure","HTN"]', 'Hypertension means your blood pressure stays higher than healthy over time, which quietly strains your heart, brain, and kidneys long before you feel anything. The good news is that it is very manageable: daily blood-pressure medication together with small lifestyle changes like cutting salt, moving more, and losing a little weight keeps it well controlled and dramatically lowers your risk of stroke and heart disease.', 'cardiovascular', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('asthma', 'Asthma', '["Bronchial Asthma"]', 'Asthma is a common long-term condition where the airways become inflamed and tighten, causing wheezing, coughing, chest tightness, and breathlessness that come and go. With a daily preventer (steroid) inhaler and a reliever inhaler on hand, most people control their symptoms well and live full, active lives.', 'respiratory', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('epilepsy', 'Epilepsy', '["Seizure Disorder"]', 'Epilepsy is a condition where the brain produces recurring seizures, and although it carries a heavy burden in Africa with many people still untreated, it is very manageable. With the right daily antiseizure medication, most people gain good seizure control and live full, active lives.', 'neurological', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('sickle-cell', 'Sickle Cell Disease', '["Sickle Cell Anaemia","SCD","HbSS"]', 'Sickle Cell Disease is an inherited blood condition where red blood cells take on a rigid, sickle shape, blocking blood flow and causing episodes of severe pain, anaemia, and a higher risk of infection. With the right care, hydroxyurea, vaccines and daily antibiotics to prevent infection, staying well hydrated, and good pain management, most people can live full lives and have fewer crises.', 'blood', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('chronic-kidney-disease', 'Chronic Kidney Disease', '["CKD","Kidney Disease","Chronic Renal Failure","Chronic Renal Disease"]', 'Chronic kidney disease means your kidneys are slowly losing their ability to filter waste and extra fluid from your blood, most often because of long-standing high blood pressure, diabetes, or HIV. The encouraging news is that controlling blood pressure and blood sugar, treating HIV, and newer kidney-protecting medicines can slow it down a lot, and even when the kidneys fail, dialysis or a transplant can keep you living well.', 'chronic', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('stroke', 'Stroke', '["Cerebrovascular Accident","CVA","Brain Attack"]', 'A stroke happens when blood flow to part of the brain is suddenly interrupted, either by a clot blocking a vessel (ischaemic) or by a bleed (haemorrhagic), so brain cells begin to die within minutes. Getting to hospital fast is critical, and for clot strokes clot-busting or clot-removal treatment can save brain tissue; with rehabilitation and steady control of blood pressure, many people recover function and lower their risk of another stroke.', 'cardiovascular', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('copd', 'COPD', '["Chronic Obstructive Pulmonary Disease","Emphysema","Chronic Bronchitis"]', 'COPD is a long-term lung condition where the airways narrow and become inflamed, making it harder to breathe out fully — most often from smoking, but also from cooking-fire smoke and other indoor air pollution common across Africa. It can''t be reversed, but stopping smoking, inhalers, pulmonary rehab, and vaccinations can ease breathlessness, cut down flare-ups, and help you stay active and well for years.', 'respiratory', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('malaria', 'Malaria', '["Plasmodium infection"]', 'Malaria is an infection caused by Plasmodium parasites spread through the bite of an infected mosquito, and it is very common across much of sub-Saharan Africa. The good news is that it is curable: when treatment is started quickly with the right antimalarial medicines (artemisinin-based combination therapy), most people recover fully, and simple steps like sleeping under a treated net help keep you safe.', 'infectious', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('hepatitis-b', 'Hepatitis B', '["HBV","Chronic Hepatitis B"]', 'Hepatitis B is a liver infection caused by the hepatitis B virus, which is common across Africa and is often carried for years without any symptoms. The good news is that a safe vaccine can prevent it, and daily antiviral tablets can keep the virus under control and protect your liver, even though they don''t fully cure it.', 'infectious', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('schistosomiasis', 'Schistosomiasis', '["Bilharzia","Snail Fever"]', 'Schistosomiasis (also called bilharzia or snail fever) is a parasitic infection caught from freshwater where certain snails live, common in parts of South Africa and across Africa. The good news is that a single course of the tablet praziquantel cures most people, and getting treated early prevents long-term damage to the bladder, bowel, and liver.', 'infectious', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('rheumatoid-arthritis', 'Rheumatoid Arthritis', '["RA"]', 'Rheumatoid arthritis is an autoimmune condition where your immune system attacks the lining of your joints, causing pain, swelling, and stiffness that''s often worst in the morning. Starting DMARD medication like methotrexate early can calm the inflammation, protect your joints from lasting damage, and help many people reach low disease activity or remission.', 'autoimmune', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('osteoarthritis', 'Osteoarthritis', '["OA","Degenerative Joint Disease"]', 'Osteoarthritis is the most common form of arthritis, where the smooth cartilage that cushions a joint gradually wears down, leading to pain, stiffness, and reduced movement, most often in the knees, hips, hands, and spine. The good news is that staying active, keeping to a healthy weight, and good pain control help most people stay mobile, and for badly worn joints, replacement surgery can dramatically restore comfort and function.', 'musculoskeletal', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('lupus', 'Lupus (SLE)', '["SLE","Systemic Lupus Erythematosus"]', 'Lupus is an autoimmune condition where the immune system mistakenly attacks the body''s own tissues, causing inflammation that can affect the skin, joints, kidneys, blood, and other organs, often with flares and quieter periods. It tends to be more common and more severe in people of African ancestry, but with the right long-term medication, most people can control their symptoms and protect their organs.', 'autoimmune', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('gout', 'Gout', '["Gouty Arthritis","Crystal Arthritis","Urate Arthropathy"]', 'Gout is a form of inflammatory arthritis caused by sharp uric-acid crystals building up in a joint, often triggering sudden, intensely painful attacks that frequently start in the big toe. The good news is that it is very treatable: daily urate-lowering medication like allopurinol can prevent future attacks for most people, while anti-inflammatories settle a flare when one strikes.', 'musculoskeletal', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('iron-deficiency-anemia', 'Iron-Deficiency Anaemia', '["Anaemia","Anemia","IDA"]', 'Iron-deficiency anaemia happens when your body doesn''t have enough iron to make healthy red blood cells, which can leave you tired, pale, and short of breath. The good news is that it''s very treatable: replacing the iron and finding and fixing the cause of the loss almost always brings your blood count and energy back to normal.', 'blood', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('schizophrenia', 'Schizophrenia', '["Psychosis","Schizophrenia spectrum"]', 'Schizophrenia is a serious but treatable mental illness that can affect how a person thinks, feels, and tells apart what is real, often bringing hallucinations, strong beliefs others do not share, and changes in motivation or emotion. With steady antipsychotic medication and good support from family and a care team, many people manage their symptoms well and live full, meaningful lives.', 'mental', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('alcohol-use-disorder', 'Alcohol Use Disorder', '["Alcoholism","AUD","Alcohol Dependence"]', 'Alcohol Use Disorder is a treatable condition where drinking becomes hard to control and starts to harm your health, relationships, or daily life, despite wanting to cut down. Recovery is very possible: a combination of counselling, peer support, and relapse-prevention medication helps many people drink less or stop, and reaching out for help is a sign of strength rather than weakness.', 'mental', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('cervical-cancer', 'Cervical Cancer', '["Cervix Cancer","Cancer of the Uterine Cervix"]', 'Cervical cancer develops in the cells of the cervix and is almost always caused by long-term infection with high-risk HPV, with HIV greatly raising the risk. The encouraging news is that it is one of the most preventable and, when caught early, most treatable cancers: HPV vaccination and regular screening stop most cases, while surgery, radiation, and chemotherapy can cure or control disease that has already developed.', 'cancer', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('heart-failure', 'Heart Failure', '["Congestive Heart Failure","CHF"]', 'Heart failure means the heart can''t pump strongly enough to meet the body''s needs, often after years of high blood pressure, a damaged heart valve, or a previous heart attack. It is a serious but very treatable condition: the right combination of daily medicines, salt and fluid awareness, and regular check-ups can ease breathlessness and swelling, keep you out of hospital, and help you live longer.', 'cardiovascular', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('fasd', 'Fetal Alcohol Spectrum Disorder', '["FASD","FAS","Foetal Alcohol Spectrum Disorder","Fetal Alcohol Syndrome"]', 'Fetal Alcohol Spectrum Disorder is a lifelong condition caused by alcohol exposure before birth, which affects how the brain and body develop and can lead to differences in learning, behaviour, and sometimes physical features. There is no cure, but starting support early and building a structured, predictable, and understanding environment at home and school makes a real difference to how well a person thrives.', 'neurological', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('coronary-artery-disease', 'Coronary Artery Disease', '["CAD","Coronary Heart Disease","Ischaemic Heart Disease"]', 'Coronary artery disease happens when the arteries that supply the heart muscle become narrowed by plaque, reducing blood flow and raising the risk of angina or heart attack. Treatment focuses on lowering cholesterol and blood pressure, stopping smoking, cardiac rehabilitation, and procedures such as stents or bypass surgery when blood flow needs to be restored.', 'cardiovascular', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('atrial-fibrillation', 'Atrial Fibrillation', '["AFib","AF","Atrial Flutter"]', 'Atrial fibrillation is an irregular heart rhythm that can make the heart beat too fast and allow blood clots to form. Care usually focuses on stroke prevention with anticoagulants when risk is high, heart-rate control, rhythm treatment for selected people, and managing triggers such as blood pressure, alcohol, sleep apnea, and thyroid disease.', 'cardiovascular', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('rheumatic-heart-disease', 'Rheumatic Heart Disease', '["RHD","Rheumatic Valve Disease"]', 'Rheumatic heart disease is damage to the heart valves after rheumatic fever, which can follow untreated strep throat, especially in childhood. Ongoing care focuses on regular penicillin to prevent repeat rheumatic fever, monitoring valve damage, treating heart failure or rhythm problems, and repairing or replacing valves when disease becomes severe.', 'cardiovascular', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('peripheral-artery-disease', 'Peripheral Artery Disease', '["PAD","Peripheral Vascular Disease","PVD"]', 'Peripheral artery disease happens when narrowed arteries reduce blood flow to the legs or other limbs, often causing calf or thigh pain when walking. Treatment focuses on stopping smoking, walking or supervised exercise, cholesterol and antiplatelet medicines, diabetes and blood-pressure control, foot care, and procedures to restore blood flow when symptoms are severe.', 'cardiovascular', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('cerebral-palsy', 'Cerebral Palsy', '["CP"]', 'Cerebral palsy is a lifelong movement and posture disability caused by early differences or injury in the developing brain. Support is usually tailored over time and can include physiotherapy, occupational therapy, speech therapy, braces, mobility aids, spasticity treatment, and school or family support.', 'disability', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('spinal-cord-injury', 'Spinal Cord Injury', '["SCI","Paraplegia","Tetraplegia","Quadriplegia"]', 'Spinal cord injury is damage to the spinal cord from trauma or illness that can change movement, sensation, bladder and bowel function, pain, and skin health below the injury level. Early rehabilitation, careful seating, mobility aids, bladder and bowel plans, skin care, pain care, and assistive technology help protect health and daily independence.', 'disability', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('limb-loss', 'Limb Loss', '["Amputation","Limb Difference","Lower Limb Amputation","Upper Limb Amputation"]', 'Limb loss can happen after injury, infection, diabetes, vascular disease, cancer, or a difference present from birth. Care often includes wound and residual-limb care, physiotherapy, occupational therapy, prosthetic rehabilitation, mobility aids, pain care, skin monitoring, and emotional support.', 'disability', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('intellectual-disability', 'Intellectual Disability', '["ID","Learning Disability","Developmental Disability"]', 'Intellectual disability begins before adulthood and affects learning, reasoning, problem-solving, and daily living skills. Support is usually long term and can include developmental therapies, communication support, adapted education, assistive technology, health checks, family support, and planning for safe independence.', 'disability', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('hearing-loss', 'Hearing Loss', '["Deafness","Hard of Hearing","Disabling Hearing Loss"]', 'Hearing loss can affect one or both ears and may change speech understanding, learning, work, safety, and social connection. Support depends on the cause and degree of loss and can include audiology care, hearing aids, cochlear implants for selected people, assistive listening tools, speech therapy, sign language, and communication planning.', 'disability', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO conditions (slug, name, aliases, description, category, created_at, updated_at) VALUES ('vision-impairment', 'Vision Impairment', '["Low Vision","Blindness","Visual Impairment"]', 'Vision impairment includes low vision and blindness that cannot be fully corrected with ordinary glasses, contact lenses, medicine, or surgery. Care may include treating the eye condition when possible, low-vision aids, vision rehabilitation, orientation and mobility training, assistive technology, home changes, and emotional support.', 'disability', (unixepoch() * 1000), (unixepoch() * 1000));

INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('ssri-sertraline', 'Sertraline (Zoloft)', 'medication', 'SSRI commonly prescribed for depression, anxiety, PTSD, OCD, panic disorder, and social anxiety.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('ssri-escitalopram', 'Escitalopram (Lexapro)', 'medication', 'SSRI used for depression and generalised anxiety; often well-tolerated.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('ssri-fluoxetine', 'Fluoxetine (Prozac)', 'medication', 'Long-half-life SSRI used for depression, OCD, and panic.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('snri-venlafaxine', 'Venlafaxine (Effexor)', 'medication', 'SNRI for depression, anxiety, panic. Dose-dependent effect on norepinephrine.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('snri-duloxetine', 'Duloxetine (Cymbalta)', 'medication', 'SNRI used for depression, anxiety, fibromyalgia, and chronic pain.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('bupropion', 'Bupropion (Wellbutrin)', 'medication', 'NDRI with activating profile; sometimes used when SSRIs cause fatigue or sexual side effects.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('mirtazapine', 'Mirtazapine', 'medication', 'Tetracyclic antidepressant; often helps sleep and appetite at lower doses.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('lamotrigine', 'Lamotrigine', 'medication', 'Mood stabiliser for bipolar depression; slow titration to avoid rash.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('lithium', 'Lithium', 'medication', 'First-line mood stabiliser for bipolar disorder; requires monitoring.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('methylphenidate', 'Methylphenidate', 'medication', 'Stimulant commonly used for ADHD in extended- and immediate-release forms.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('amphetamine', 'Amphetamine salts (Adderall/Vyvanse)', 'medication', 'Stimulant family used for ADHD.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('atomoxetine', 'Atomoxetine (Strattera)', 'medication', 'Non-stimulant NRI for ADHD.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('guanfacine', 'Guanfacine', 'medication', 'Alpha-2 agonist used for ADHD and hyperarousal.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('prazosin', 'Prazosin', 'medication', 'Alpha-1 blocker often used off-label for PTSD nightmares.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('levothyroxine', 'Levothyroxine', 'medication', 'Synthetic T4 thyroid hormone replacement, first-line for hypothyroidism.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('metformin', 'Metformin', 'medication', 'First-line oral medication for type 2 diabetes.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('ldn', 'Low-Dose Naltrexone', 'medication', 'Off-label use at 0.5-4.5mg for fibromyalgia, ME/CFS, and autoimmune conditions.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('propranolol', 'Propranolol', 'medication', 'Beta-blocker used for migraine prevention, performance anxiety, and POTS.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('cgrp-inhibitor', 'CGRP inhibitor (Aimovig, Emgality)', 'medication', 'Newer class of migraine preventives targeting the CGRP pathway.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('triptan', 'Triptans (Sumatriptan)', 'medication', 'Acute migraine abortive medication family.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('cbt', 'CBT', 'therapy', 'Cognitive Behavioural Therapy — structured short-to-medium term therapy with strong evidence for depression, anxiety, and many other conditions.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('dbt', 'DBT', 'therapy', 'Dialectical Behaviour Therapy — skills-based approach originally developed for BPD, useful broadly for emotional regulation.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('emdr', 'EMDR', 'therapy', 'Eye Movement Desensitization and Reprocessing — evidence-based trauma therapy.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('ifs', 'IFS', 'therapy', 'Internal Family Systems — parts-based therapy for trauma, self-compassion, and emotional integration.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('somatic-experiencing', 'Somatic Experiencing', 'therapy', 'Body-based trauma therapy that focuses on nervous system regulation.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('act', 'ACT', 'therapy', 'Acceptance and Commitment Therapy — mindfulness-plus-values approach.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('erp', 'ERP for OCD', 'therapy', 'Exposure and Response Prevention — gold-standard therapy for OCD.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('psychodynamic', 'Psychodynamic therapy', 'therapy', 'Depth-oriented exploration of patterns and early relationships.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('cbt-i', 'CBT-I', 'therapy', 'Cognitive Behavioural Therapy for Insomnia — first-line for chronic insomnia.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('meditation', 'Meditation practice', 'lifestyle', 'Consistent mindfulness or concentration practice; many evidence-based forms.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('yoga', 'Yoga', 'lifestyle', 'Gentle movement + breath. Research support for depression, anxiety, chronic pain.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('walking', 'Daily walks', 'lifestyle', 'Simple, repeatable movement that compounds; strong evidence across mood and metabolic conditions.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('strength-training', 'Strength training', 'lifestyle', 'Progressive resistance work — depression, diabetes, and chronic pain benefit.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('cold-exposure', 'Cold exposure', 'lifestyle', 'Short cold showers or plunges; reported benefits for mood and inflammation (research is early).', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('sleep-hygiene', 'Sleep hygiene', 'lifestyle', 'Consistent bedtime, light management, stimulus control. Foundational for most conditions.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('low-fodmap', 'Low-FODMAP diet', 'lifestyle', 'Elimination diet commonly trialled for IBS.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('gluten-free', 'Gluten-free diet', 'lifestyle', 'Mandatory for celiac; some report benefit for Hashimoto''s and fibromyalgia.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('autoimmune-protocol', 'AIP (Autoimmune Protocol)', 'lifestyle', 'Elimination-style diet often tried for autoimmune flares.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('pacing', 'Pacing', 'lifestyle', 'Energy management strategy for ME/CFS, long COVID, and chronic pain.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('vitamin-d', 'Vitamin D', 'supplement', 'Common deficiency affecting many conditions; dosage is individual.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('magnesium', 'Magnesium', 'supplement', 'Often used for sleep, migraine, fibromyalgia, and muscle tension.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('omega-3', 'Omega-3 (fish oil)', 'supplement', 'Anti-inflammatory; evidence for mood and cardiovascular outcomes.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('l-theanine', 'L-theanine', 'supplement', 'Calming amino acid from green tea; used for anxiety and sleep.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('melatonin', 'Melatonin', 'supplement', 'Sleep-timing hormone; low-dose often more effective than high-dose.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('saffron', 'Saffron extract', 'supplement', 'Herbal extract with growing evidence for mild-to-moderate depression.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('nac', 'N-Acetylcysteine (NAC)', 'supplement', 'Glutathione precursor used in OCD, trichotillomania, and bipolar.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('b-complex', 'B-complex vitamins', 'supplement', 'Especially B12/folate; matters for energy, mood, and methylation.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('light-therapy', 'Light therapy box', 'device', '10,000 lux morning exposure for seasonal depression and circadian disorders.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('tens', 'TENS unit', 'device', 'Transcutaneous electrical nerve stimulation for chronic pain.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('cpap', 'CPAP', 'device', 'Continuous Positive Airway Pressure device for sleep apnea.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('compression-garments', 'Compression garments', 'device', 'Used for POTS and circulatory support.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('art-tld', 'Antiretroviral Therapy (TLD - Tenofovir/Lamivudine/Dolutegravir)', 'medication', 'The standard first-line single-pill HIV regimen in South Africa, combining two NRTIs (tenofovir, lamivudine) with the integrase inhibitor dolutegravir. Taken once daily, it suppresses the virus to undetectable levels so it can''t be transmitted (U=U) and keeps the immune system healthy.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('dolutegravir', 'Dolutegravir (Integrase Inhibitor)', 'medication', 'A potent, well-tolerated HIV integrase inhibitor that blocks the virus from inserting its genes into your cells. It''s the backbone of modern antiretroviral therapy, has a high barrier to resistance, and is the preferred third agent in first-line treatment.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('tenofovir-emtricitabine-prep', 'PrEP (Tenofovir/Emtricitabine)', 'medication', 'Pre-exposure prophylaxis: a daily pill taken by HIV-negative people at risk to prevent infection. Highly effective when taken consistently, it''s a cornerstone of HIV prevention alongside condoms and testing.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('cotrimoxazole', 'Co-trimoxazole (Prophylactic Antibiotic)', 'medication', 'A combination antibiotic (sulfamethoxazole/trimethoprim) given to people with HIV and low immunity to prevent opportunistic infections like PCP pneumonia. Also used to treat a range of bacterial infections.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('tb-rhze-regimen', 'Anti-TB Combination Therapy (Rifampicin/Isoniazid/Pyrazinamide/Ethambutol)', 'medication', 'The standard curative regimen for drug-sensitive tuberculosis: four antibiotics taken together for an intensive phase, then two for continuation. Completing the full course (usually 6 months) is essential to cure TB and prevent drug-resistant strains.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('isoniazid-preventive-therapy', 'TB Preventive Therapy (Isoniazid)', 'medication', 'Isoniazid taken on its own (or with rifapentine) to stop latent TB infection from becoming active disease. Especially important for people living with HIV and close contacts of TB patients.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('bedaquiline', 'Bedaquiline (Anti-TB, Drug-Resistant)', 'medication', 'A newer oral medication central to treating multidrug-resistant TB. It blocks the energy-producing machinery of the TB bacterium and has transformed DR-TB into a largely curable, injection-free, oral treatment.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('ace-inhibitor', 'ACE Inhibitors (e.g. Enalapril, Lisinopril)', 'medication', 'Blood-pressure medications that relax blood vessels by blocking the angiotensin-converting enzyme. They protect the heart and kidneys and are first-line for hypertension, heart failure, and kidney disease, especially with diabetes.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('arb', 'ARBs (e.g. Losartan, Telmisartan)', 'medication', 'Angiotensin receptor blockers lower blood pressure and protect the kidneys, similar to ACE inhibitors but without the common dry cough. Used for hypertension, heart failure, and to slow chronic kidney disease.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('calcium-channel-blocker', 'Calcium Channel Blockers (e.g. Amlodipine)', 'medication', 'Blood-pressure medications that relax and widen arteries by blocking calcium entry into vessel walls. Amlodipine is a widely used, effective first-line option, particularly suited to many people of African ancestry.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('thiazide-diuretic', 'Thiazide Diuretics (e.g. Hydrochlorothiazide)', 'medication', 'Water pills that help the kidneys remove excess salt and fluid, lowering blood pressure. They''re an inexpensive, effective first-line antihypertensive often combined with other classes.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('loop-diuretic', 'Loop Diuretics (e.g. Furosemide)', 'medication', 'Powerful water pills that clear fluid overload, easing breathlessness and swelling in heart failure and advanced kidney disease. They act quickly on the kidneys to remove excess salt and water.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('beta-blocker', 'Beta-Blockers (e.g. Bisoprolol, Carvedilol)', 'medication', 'Medications that slow the heart and reduce its workload. They''re a core part of heart-failure therapy that improves survival, and are also used for high blood pressure and certain abnormal heart rhythms.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('inhaled-corticosteroid', 'Inhaled Corticosteroid (Controller Inhaler)', 'medication', 'The cornerstone preventer inhaler for asthma, taken daily to calm airway inflammation and prevent attacks. Used consistently it dramatically reduces symptoms, flare-ups, and the need for reliever inhalers.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('saba-reliever', 'Reliever Inhaler (Short-Acting Beta-Agonist, e.g. Salbutamol)', 'medication', 'A quick-acting rescue inhaler that opens tight airways within minutes during an asthma or COPD flare. It relieves wheezing and breathlessness but is not a substitute for a daily controller inhaler.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('ics-laba-inhaler', 'Combination Inhaler (Steroid + Long-Acting Bronchodilator)', 'medication', 'A single inhaler pairing an inhaled steroid with a long-acting bronchodilator for sustained control of asthma and COPD. It both reduces inflammation and keeps airways open over many hours.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('laba-lama-inhaler', 'Long-Acting Bronchodilator Inhaler (LABA/LAMA)', 'medication', 'Maintenance inhalers for COPD that keep airways relaxed and open for 12-24 hours, easing breathlessness and reducing flare-ups. Often combined as a dual bronchodilator for moderate to severe disease.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('antiseizure-medication', 'Antiseizure Medication (e.g. Carbamazepine, Valproate, Levetiracetam)', 'medication', 'Daily medications that stabilise electrical activity in the brain to prevent seizures. Most people with epilepsy achieve good seizure control on a single well-chosen drug, allowing a normal, safe daily life.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('hydroxyurea', 'Hydroxyurea (for Sickle Cell)', 'medication', 'A foundational sickle cell medication that boosts protective fetal haemoglobin, reducing painful crises, acute chest episodes, and the need for transfusions. Taken daily, it can substantially improve quality and length of life.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('penicillin-prophylaxis', 'Penicillin Prophylaxis (Sickle Cell)', 'medication', 'Daily preventive penicillin given to young children with sickle cell disease to guard against life-threatening pneumococcal infections, to which they are especially vulnerable. A simple, life-saving measure paired with vaccination.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('folic-acid', 'Folic Acid', 'supplement', 'A B-vitamin supplement that supports the rapid production of red blood cells. It''s routinely given in sickle cell disease and other chronic anaemias, and before/during pregnancy to prevent birth defects.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('tenofovir-hbv', 'Tenofovir (Hepatitis B Antiviral)', 'medication', 'A once-daily antiviral that powerfully suppresses the hepatitis B virus, halting liver damage and lowering the risk of cirrhosis and liver cancer. Treatment is usually long-term and well tolerated.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('entecavir', 'Entecavir (Hepatitis B Antiviral)', 'medication', 'A potent oral antiviral for chronic hepatitis B that keeps the virus suppressed with a high barrier to resistance. Taken daily, it protects the liver from ongoing inflammation and scarring.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('hepatitis-b-vaccine', 'Hepatitis B Vaccine', 'medication', 'A safe, highly effective vaccine that prevents hepatitis B infection and the liver disease and cancer it can cause. Given as a routine infant series and to at-risk adults.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('praziquantel', 'Praziquantel (for Schistosomiasis)', 'medication', 'The curative single-course treatment for schistosomiasis (bilharzia), a parasitic infection from contaminated freshwater. It clears the worms quickly and is also used in community deworming campaigns.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('act-antimalarial', 'Artemisinin-Based Combination Therapy (Antimalarial)', 'medication', 'The fast, curative first-line treatment for uncomplicated malaria, pairing artemisinin with a partner drug to wipe out the parasite and prevent resistance. Prompt treatment is critical to avoid severe, life-threatening disease.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('malaria-prophylaxis', 'Malaria Prophylaxis (Preventive Antimalarials)', 'medication', 'Preventive antimalarial tablets taken by travellers and some residents in high-risk areas to stop infection before it starts. Used alongside bed nets and insect repellent for layered protection.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('methotrexate', 'Methotrexate (DMARD)', 'medication', 'The anchor disease-modifying drug for rheumatoid arthritis, taken weekly to calm the overactive immune system and prevent joint destruction. Starting it early changes the course of the disease and preserves function.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('sulfasalazine', 'Sulfasalazine (DMARD)', 'medication', 'A disease-modifying antirheumatic drug used alone or with methotrexate to reduce joint inflammation and slow damage in rheumatoid arthritis. An affordable, well-established option.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('biologic-dmard', 'Biologic DMARDs (e.g. TNF Inhibitors)', 'medication', 'Injectable targeted therapies that block specific immune signals driving rheumatoid arthritis and other autoimmune diseases. Used when standard DMARDs aren''t enough, they can bring inflammation under tight control.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('hydroxychloroquine', 'Hydroxychloroquine (for Lupus & RA)', 'medication', 'A foundational antimalarial-derived drug used long-term in lupus and rheumatoid arthritis to reduce flares, protect organs, and improve survival. It''s gentle on the immune system and a cornerstone of lupus care.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('corticosteroid-oral', 'Oral Corticosteroids (e.g. Prednisone)', 'medication', 'Powerful anti-inflammatory tablets used in short bursts or low doses to control flares of autoimmune disease, asthma, and other inflammatory conditions. Effective and fast-acting, they''re used carefully to limit side effects.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('immunosuppressant', 'Immunosuppressants (e.g. Azathioprine, Mycophenolate)', 'medication', 'Medications that dampen an overactive immune system to protect organs in lupus and other autoimmune diseases, particularly when the kidneys or other organs are involved. Used to induce and maintain remission.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('allopurinol', 'Allopurinol (Urate-Lowering Therapy)', 'medication', 'The mainstay long-term medication for gout, taken daily to lower uric acid levels and dissolve the crystals that cause attacks. Consistent use prevents future flares and joint damage.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('colchicine', 'Colchicine (Anti-Inflammatory for Gout)', 'medication', 'An anti-inflammatory used to settle acute gout flares and to prevent them when starting urate-lowering therapy. It targets the specific inflammation triggered by urate crystals.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('nsaid', 'NSAIDs (Anti-Inflammatory Painkillers, e.g. Ibuprofen)', 'medication', 'Common anti-inflammatory painkillers used for gout flares, osteoarthritis, and other painful inflammatory conditions. They relieve pain and swelling but are used cautiously in people with kidney, heart, or stomach concerns.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('oral-iron', 'Oral Iron Supplements (e.g. Ferrous Sulfate)', 'supplement', 'Iron tablets that replenish the body''s stores to correct iron-deficiency anaemia, restoring energy and healthy red blood cells. Treating the underlying cause of the iron loss is just as important as the supplement.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('iv-iron', 'Intravenous Iron', 'procedure', 'Iron given directly into a vein to rapidly correct iron-deficiency anaemia when oral iron isn''t tolerated, isn''t working, or stores need replenishing quickly. Often used in kidney disease and heavy menstrual blood loss.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('antipsychotic', 'Antipsychotic Medication (e.g. Risperidone, Olanzapine)', 'medication', 'The mainstay treatment for schizophrenia, helping to reduce hallucinations, delusions, and disordered thinking. Taken consistently alongside psychosocial support, they help people stay well and engaged in daily life.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('long-acting-antipsychotic', 'Long-Acting Injectable Antipsychotic', 'medication', 'An antipsychotic given as an injection every few weeks instead of daily pills, helping maintain steady treatment for schizophrenia. It eases the burden of remembering daily doses and reduces relapse.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('statin', 'Statins (Cholesterol-Lowering, e.g. Atorvastatin)', 'medication', 'Daily medications that lower cholesterol and stabilise artery plaque, cutting the risk of heart attack and stroke. They''re a key part of secondary prevention after a stroke or heart disease.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('antiplatelet', 'Antiplatelet Therapy (e.g. Aspirin, Clopidogrel)', 'medication', 'Medications that make blood platelets less sticky to prevent clots, central to stopping a second stroke or heart attack. Low-dose aspirin or clopidogrel is a cornerstone of secondary prevention.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('anticoagulant', 'Anticoagulants (Blood Thinners, e.g. Warfarin, DOACs)', 'medication', 'Blood thinners that prevent dangerous clots, used to reduce stroke risk in conditions like atrial fibrillation and to treat clots. They require attention to dosing and, for some, regular monitoring.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('thrombolysis', 'Clot-Busting Therapy (Thrombolysis)', 'procedure', 'An emergency treatment for acute ischaemic stroke that dissolves the blocking clot if given within a few hours of symptoms. Fast treatment can dramatically reduce long-term disability.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('naltrexone-aud', 'Naltrexone (for Alcohol Use Disorder)', 'medication', 'A medication that reduces alcohol cravings and the pleasurable ''reward'' from drinking, supporting people in cutting down or staying abstinent. Used alongside counselling and support groups.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('acamprosate', 'Acamprosate (for Alcohol Use Disorder)', 'medication', 'A relapse-prevention medication that helps stabilise brain chemistry disrupted by long-term drinking, easing the urge to drink during recovery. Best combined with psychosocial support.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('disulfiram', 'Disulfiram (for Alcohol Use Disorder)', 'medication', 'A medication that causes an unpleasant reaction if alcohol is consumed, acting as a deterrent to support abstinence. Used in motivated people as part of a structured recovery plan.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('thiamine', 'Thiamine (Vitamin B1)', 'supplement', 'An essential B-vitamin given to people with alcohol use disorder to prevent serious brain damage (Wernicke''s encephalopathy) caused by deficiency. A simple, protective supplement during recovery.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('hpv-vaccine', 'HPV Vaccine', 'medication', 'A vaccine that protects against the human papillomavirus strains that cause most cervical cancer. Given to adolescents before exposure, it is one of the most effective tools for preventing cervical cancer.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('cervical-screening', 'Cervical Screening (Pap Smear / HPV Test)', 'procedure', 'A simple screening test that detects precancerous changes or HPV on the cervix before cancer develops, allowing early treatment. Regular screening is one of the most powerful ways to prevent cervical cancer deaths.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('chemotherapy', 'Chemotherapy', 'medication', 'Anti-cancer drugs that kill or slow rapidly dividing cancer cells, used to treat cervical and other cancers, sometimes alongside radiation or surgery. Treatment plans are tailored to the cancer type and stage.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('radiotherapy', 'Radiation Therapy', 'procedure', 'Targeted high-energy radiation that destroys cancer cells, a key treatment for cervical cancer often combined with chemotherapy. It can be curative or used to relieve symptoms in advanced disease.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('hemodialysis', 'Dialysis (Haemodialysis / Peritoneal)', 'procedure', 'A life-sustaining treatment for advanced kidney failure that filters waste and excess fluid from the blood when the kidneys can no longer do so. It is done regularly at a centre or at home while awaiting transplant.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('kidney-transplant', 'Kidney Transplant', 'procedure', 'Surgical replacement of failed kidneys with a healthy donor kidney, offering the best quality and length of life for many people with end-stage kidney disease. It requires lifelong anti-rejection medication.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('sglt2-inhibitor', 'SGLT2 Inhibitors (Kidney & Heart Protective)', 'medication', 'Once-daily tablets originally for diabetes that are now proven to slow chronic kidney disease and improve heart-failure outcomes, even without diabetes. They protect the kidneys and heart beyond their glucose-lowering effect.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('erythropoietin', 'Erythropoietin (Anaemia of Kidney Disease)', 'medication', 'An injectable hormone that stimulates the bone marrow to make red blood cells, treating the anaemia that often comes with advanced kidney disease. It restores energy and reduces the need for transfusions.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('physiotherapy', 'Physiotherapy', 'therapy', 'Hands-on and exercise-based rehabilitation to restore movement, strength, and function after stroke, surgery, or injury, and to manage arthritis and chronic pain. A physiotherapist tailors a programme to your goals.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('stroke-rehabilitation', 'Stroke Rehabilitation', 'therapy', 'A coordinated programme of physical, occupational, and speech therapy that helps people regain independence and skills after a stroke. Starting early and continuing consistently leads to the best recovery.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('occupational-therapy', 'Occupational Therapy', 'therapy', 'Therapy that helps people regain or adapt the everyday skills needed for daily living and work, whether after a stroke, with arthritis, or with a developmental condition. Focuses on practical independence and meaningful activity.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('speech-therapy', 'Speech and Language Therapy', 'therapy', 'Therapy to rebuild communication and safe swallowing after a stroke or brain injury, and to support children with developmental and language difficulties. A speech therapist tailors exercises to each person''s needs.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('pulmonary-rehabilitation', 'Pulmonary Rehabilitation', 'therapy', 'A structured programme of supervised exercise, breathing techniques, and education for people with COPD and other lung diseases. It improves breathlessness, stamina, and confidence in daily activities.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('smoking-cessation', 'Smoking Cessation Support', 'therapy', 'Counselling and structured support to help people quit smoking, the single most important step in slowing COPD and reducing heart and cancer risk. Often combined with nicotine replacement or medication.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('nicotine-replacement', 'Nicotine Replacement Therapy', 'medication', 'Patches, gum, or lozenges that supply controlled nicotine to ease cravings and withdrawal while quitting smoking. They roughly double the chance of quitting successfully when paired with support.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('support-group', 'Peer Support Groups (e.g. 12-Step / SMART Recovery)', 'therapy', 'Facilitated peer groups where people facing the same condition share experience, accountability, and encouragement. Particularly valuable in alcohol and substance recovery, and for chronic illness coping.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('joint-replacement', 'Joint Replacement Surgery', 'procedure', 'Surgical replacement of a severely damaged hip or knee joint with an artificial one, used for advanced osteoarthritis when other treatments no longer control pain. It can dramatically restore mobility and quality of life.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('weight-management', 'Weight Management', 'lifestyle', 'Achieving and maintaining a healthier weight through diet and activity, which reduces load on arthritic joints, lowers blood pressure, and improves outcomes across many chronic conditions. First-line and often highly effective.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('dash-diet', 'DASH / Low-Salt Diet', 'lifestyle', 'An eating pattern rich in fruit, vegetables, and wholegrains and low in salt, proven to lower blood pressure. A central lifestyle measure for hypertension that also benefits the heart and kidneys.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('blood-transfusion', 'Blood Transfusion', 'procedure', 'Giving donor red blood cells to rapidly treat severe anaemia or blood loss, and used in sickle cell disease to prevent or manage complications. A life-saving measure in acute crises.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('early-intervention-fasd', 'Early Developmental Intervention (FASD)', 'therapy', 'Coordinated early therapies, structured routines, and educational and family support for children with fetal alcohol spectrum disorder. Early, consistent intervention improves learning, behaviour, and long-term outcomes.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('ras-inhibitor-heart-failure', 'ARNI (Sacubitril/Valsartan, Heart Failure)', 'medication', 'A modern heart-failure medication combining two actions to relax blood vessels and reduce strain on the heart. As part of guideline-directed therapy it improves survival and reduces hospital admissions.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('mra', 'Mineralocorticoid Receptor Antagonists (e.g. Spironolactone)', 'medication', 'Medications that block a hormone driving fluid retention and heart strain, improving survival in heart failure and helping control resistant high blood pressure. A key pillar of guideline-directed heart-failure therapy.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('long-acting-pain-management', 'Pain Management Program', 'therapy', 'A structured, multidisciplinary approach combining medication, physical therapy, and coping strategies to manage chronic and crisis pain, such as in sickle cell disease and severe arthritis. Aims to restore function and quality of life.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('art-adherence-counseling', 'ART Adherence Counselling and Support', 'therapy', 'Structured counselling, education, and reminder support that helps people take their antiretroviral therapy consistently every day. Good adherence is what keeps the virus suppressed, protects the immune system, and makes HIV untransmittable, so this support is essential to treatment success rather than optional.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('pyridoxine-b6', 'Pyridoxine (Vitamin B6)', 'supplement', 'Taken alongside isoniazid during TB treatment to prevent the nerve tingling and numbness (peripheral neuropathy) that isoniazid can cause. Routinely co-prescribed, especially for people with HIV, diabetes, malnutrition, or in pregnancy.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('nutritional-support', 'Nutritional Support', 'lifestyle', 'Adequate protein and calorie intake, plus correcting deficiencies, to help the body recover from the weight loss and wasting that TB causes. An adjunct that supports recovery and improves treatment outcomes, never a replacement for TB antibiotics.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('montelukast', 'Montelukast (Leukotriene Receptor Antagonist)', 'medication', 'A daily anti-inflammatory tablet used as an add-on or alternative controller, particularly helpful for allergy-related and exercise-induced asthma. It is an add-on, not a replacement for a steroid inhaler.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('asthma-biologic', 'Biologic Therapy for Severe Asthma (e.g. Omalizumab, Mepolizumab)', 'medication', 'Injectable targeted antibodies for severe, hard-to-control asthma that reduce flare-ups by blocking specific inflammatory pathways such as IgE or eosinophils. Reserved for severe disease that remains uncontrolled on inhalers.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('asthma-action-plan', 'Written Asthma Action Plan', 'therapy', 'A personalised, clinician-written plan that guides daily inhaler use and how to step up treatment early during a flare, helping reduce emergency visits and hospital admissions.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('epilepsy-surgery', 'Epilepsy Surgery', 'procedure', 'Surgical removal or disconnection of the seizure-generating brain area, considered for drug-resistant focal epilepsy and potentially curative when a single seizure focus is identified.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('ketogenic-diet', 'Ketogenic Diet', 'lifestyle', 'A high-fat, low-carbohydrate medically supervised diet used as an adjunct for drug-resistant epilepsy, especially in children, to reduce seizure frequency. It does not replace antiseizure medication.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('vagus-nerve-stimulation', 'Vagus Nerve Stimulation (VNS)', 'device', 'An implanted device that sends regular mild electrical pulses to the vagus nerve, used as an add-on therapy to reduce seizure frequency in drug-resistant epilepsy.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('hydration-therapy', 'Hydration (oral and IV fluids)', 'lifestyle', 'Keeping well hydrated with fluids, and IV fluids during a crisis, helps prevent and ease vaso-occlusive pain episodes in sickle cell disease. A simple, central part of everyday self-care and acute management, used alongside (not instead of) hydroxyurea and infection prevention.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('l-glutamine-scd', 'L-glutamine (Endari)', 'supplement', 'An oral amino acid therapy shown to modestly reduce the frequency of pain crises in sickle cell disease. Used as an add-on to hydroxyurea where available, not as a replacement for it.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('pneumococcal-vaccination', 'Pneumococcal vaccination (plus meningococcal, Hib, influenza)', 'procedure', 'People with sickle cell disease have a damaged or absent spleen and are at high risk of life-threatening infection from pneumococcus and other bacteria. Pneumococcal vaccines (PCV and PPSV23), along with Hib, meningococcal and yearly flu vaccines, are a core preventive measure given alongside daily penicillin in young children.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('thrombectomy', 'Mechanical Thrombectomy (Endovascular Clot Removal)', 'procedure', 'An emergency procedure for ischaemic (clot) stroke in which a catheter is threaded into the blocked brain artery and the clot is physically removed, restoring blood flow. For eligible large-vessel-occlusion strokes it is one of the most effective acute treatments for reducing long-term disability, generally within about 6 hours (sometimes up to 24 hours in selected patients).', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('vaccination-flu-pneumococcal', 'Flu and Pneumococcal Vaccination', 'procedure', 'Yearly influenza vaccination and pneumococcal vaccination are recommended for people with COPD to lower the risk of chest infections that trigger dangerous flare-ups and hospital admissions.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('long-term-oxygen-therapy', 'Long-Term Oxygen Therapy', 'device', 'For people with severe COPD and persistently low blood oxygen, breathing extra oxygen for at least 15 hours a day eases breathlessness and is one of the few treatments shown to help people live longer. Oxygen levels must be confirmed by testing first.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('iv-artesunate', 'Intravenous Artesunate (Severe Malaria)', 'medication', 'The WHO first-line, life-saving treatment for severe or complicated malaria, given by injection in hospital. Large trials showed it lowers death rates compared with older quinine treatment, especially in African children.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('insecticide-treated-nets', 'Insecticide-Treated Bed Nets', 'device', 'Long-lasting insecticidal nets that protect people from mosquito bites while they sleep. A cornerstone of malaria prevention that has substantially reduced infections and deaths across endemic regions.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('malaria-vaccine', 'Malaria Vaccine (RTS,S / R21)', 'medication', 'WHO-recommended vaccines that give children partial protection against malaria and reduce severe disease and deaths. Used alongside nets and prompt treatment rather than as a replacement for them.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('peginterferon-alfa', 'Pegylated Interferon Alfa', 'medication', 'A weekly injection given for a fixed course (usually 48 weeks) that boosts the immune system to control hepatitis B. It can lead to a finite, off-treatment response in carefully selected patients but has more side effects than oral antivirals and is not suitable for advanced liver disease.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('hbv-birth-dose-vaccine', 'Hepatitis B Birth-Dose Vaccine', 'procedure', 'A hepatitis B vaccine dose given within 24 hours of birth, which is the single most effective step to prevent mother-to-child transmission. It is a WHO-recommended cornerstone of eliminating hepatitis B in high-prevalence regions like Africa.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('hepatitis-b-immunoglobulin', 'Hepatitis B Immunoglobulin (HBIG)', 'medication', 'Ready-made antibodies given for rapid, short-term protection after exposure to hepatitis B, such as a newborn of an infected mother or after a needlestick injury. It is given alongside the vaccine to provide immediate cover while the vaccine builds lasting immunity.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('liver-transplant-hbv', 'Liver Transplant', 'procedure', 'Replacement of a failing liver in people who develop end-stage liver disease or liver cancer from chronic hepatitis B. With antiviral medication and immunoglobulin to prevent reinfection of the new liver, long-term outcomes are very good.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('praziquantel-repeat-dose', 'Praziquantel repeat dose (4-6 weeks later)', 'medication', 'A second course of praziquantel given a few weeks after the first, because the drug does not kill immature worms; repeating the dose catches parasites that have since matured and raises cure rates.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('praziquantel-preventive-chemotherapy', 'Praziquantel mass drug administration (preventive chemotherapy)', 'medication', 'WHO-recommended community-wide deworming with praziquantel, especially for school-age children in endemic areas, to reduce worm burden, prevent complications, and lower transmission across the population.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('oxamniquine', 'Oxamniquine', 'medication', 'An older oral antiparasitic effective only against Schistosoma mansoni (intestinal bilharzia). Now rarely used and of limited availability since praziquantel covers all species, but a historical/backup option where praziquantel resistance or intolerance is a concern.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('artesunate-adjunct', 'Artemisinin derivatives (artesunate) as adjunct', 'medication', 'Antimalarial drugs that also kill young, immature schistosome worms which praziquantel misses. Used in some settings alongside praziquantel or for prevention, complementing rather than replacing the standard cure.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('safe-water-sanitation', 'Safe water access and improved sanitation', 'lifestyle', 'Avoiding contact with potentially infested fresh water and using safe water plus proper toilets/latrines to prevent egg-contaminated urine and stool from reaching snail habitats. A key prevention and transmission-control measure, not a cure for existing infection.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('snail-control', 'Snail control (molluscicides and habitat management)', 'lifestyle', 'Reducing the freshwater snails that host the parasite, through molluscicides or environmental management, to interrupt the transmission cycle at the community level. A public-health prevention measure that complements drug treatment, not an individual cure.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('leflunomide', 'Leflunomide (DMARD)', 'medication', 'A conventional synthetic DMARD that suppresses overactive immune cells, used alone or alongside methotrexate to control rheumatoid arthritis when methotrexate isn''t suitable or isn''t enough.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('intra-articular-corticosteroid', 'Intra-articular Corticosteroid Injection', 'procedure', 'A steroid injected directly into the affected joint to reduce inflammation and provide short-term pain relief during flares; benefit typically lasts weeks to a few months and injections are limited per year.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('belimumab', 'Belimumab (Biologic for Lupus)', 'medication', 'A targeted biologic (B-lymphocyte stimulator inhibitor) approved for systemic lupus, used as add-on therapy to reduce flares and steroid dependence in active disease, including lupus nephritis.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('sun-protection', 'Sun Protection (UV Avoidance & Sunscreen)', 'lifestyle', 'Daily broad-spectrum sunscreen, protective clothing, and avoiding peak UV are important in lupus because sunlight commonly triggers skin and systemic flares. A core preventive measure alongside medication, not a replacement for it.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('febuxostat', 'Febuxostat (Urate-Lowering Therapy)', 'medication', 'A xanthine-oxidase inhibitor that lowers uric acid, used as an alternative urate-lowering therapy when allopurinol is not tolerated or fails to reach the target urate level.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('low-purine-diet', 'Low-Purine Diet', 'lifestyle', 'Reducing high-purine foods such as red and organ meats, shellfish, and sugary drinks to help lower uric acid as an adjunct to medication, not a replacement for it.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('alcohol-reduction', 'Alcohol Reduction', 'lifestyle', 'Cutting back on alcohol, especially beer and spirits, to reduce uric-acid spikes and lower the frequency of gout flares alongside medical treatment.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('vitamin-c', 'Vitamin C Supplement', 'supplement', 'Vitamin C may modestly lower serum uric acid; an emerging-evidence adjunct only, not a substitute for urate-lowering medication.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('deworming-therapy', 'Deworming Therapy (e.g. Albendazole/Mebendazole)', 'medication', 'Antiparasitic tablets that clear intestinal worms such as hookworm, a major and treatable cause of iron-deficiency anaemia in Africa. Used alongside iron replacement to stop ongoing blood and iron loss when worms are the cause.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('vitamin-c-cofactor', 'Vitamin C (with iron)', 'supplement', 'Taking vitamin C, or eating vitamin-C-rich foods, with iron tablets boosts how much iron the gut absorbs. An inexpensive adjunct that makes iron repletion more effective, not a stand-alone treatment.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('iron-rich-diet', 'Iron-Rich Diet', 'lifestyle', 'Eating more iron-rich foods like red meat, liver, beans, lentils, and dark leafy greens helps maintain iron levels and prevent relapse. A supportive measure that complements, but cannot replace, medical iron treatment in established anaemia.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('clozapine', 'Clozapine', 'medication', 'The most effective antipsychotic for treatment-resistant schizophrenia, used when two other antipsychotics have not worked. It requires regular blood monitoring because of a rare risk to white blood cells, but can be life-changing for symptoms that have not responded to other medicines.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('motivational-interviewing', 'Motivational Interviewing / Enhancement Therapy', 'therapy', 'A collaborative, non-judgemental counselling style that strengthens a person''s own motivation to change drinking. Strong evidence in alcohol use disorder, especially as a brief intervention and to engage people in further treatment.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('exercise-program', 'Structured Exercise Program', 'lifestyle', 'Regular aerobic and strength activity used as an adjunct in recovery to reduce cravings, improve mood and sleep, and support overall health. Helpful alongside — never instead of — counselling and relapse-prevention medication.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('radical-hysterectomy', 'Surgery (Radical Hysterectomy / Conization)', 'procedure', 'Surgical removal of the cancer, ranging from a cone biopsy or trachelectomy for very early disease to a radical hysterectomy removing the cervix, uterus, and nearby tissue. Often curative for early-stage cervical cancer.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('chemoradiation', 'Concurrent Chemoradiation (with Brachytherapy)', 'procedure', 'The standard curative treatment for locally advanced cervical cancer: cisplatin-based chemotherapy given alongside external-beam radiation plus internal radiation (brachytherapy) to maximise tumour control.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('cardiac-rehabilitation', 'Cardiac Rehabilitation', 'therapy', 'Medically supervised exercise, education, risk-factor coaching, and stress support after a heart attack, heart failure, angioplasty, or heart surgery. It improves fitness, confidence, and future heart health.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('coronary-angioplasty-stent', 'Coronary Angioplasty and Stent', 'procedure', 'A procedure that opens a narrowed heart artery with a balloon and often places a stent to keep blood flowing. It can relieve angina and is urgent treatment for many heart attacks.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('rate-control-medicine', 'Rate-Control Medicine', 'medication', 'Medicines such as beta-blockers, calcium channel blockers, or digoxin that slow a fast heart rate in atrial fibrillation. Better rate control can ease palpitations, breathlessness, and fatigue.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('electrical-cardioversion', 'Electrical Cardioversion', 'procedure', 'A planned procedure that uses a brief electrical shock under sedation to reset an abnormal heart rhythm. It is used for selected people with atrial fibrillation or atrial flutter.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('catheter-ablation', 'Catheter Ablation', 'procedure', 'A heart rhythm procedure that targets small areas of tissue causing abnormal electrical signals. It can reduce atrial fibrillation episodes for selected people when medicines are not enough.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('valve-surgery', 'Valve Repair or Replacement', 'procedure', 'Surgery or catheter-based treatment to fix a damaged heart valve when valve disease is severe or causing heart failure. It can relieve breathlessness and prevent further heart strain.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('penicillin-prophylaxis-rhd', 'Penicillin Prophylaxis for Rheumatic Heart Disease', 'medication', 'Regular penicillin injections or tablets used after rheumatic fever to prevent repeat strep infections that can cause more valve damage. It is a major preventive step in rheumatic heart disease care.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('peripheral-angioplasty-stent', 'Peripheral Angioplasty and Stent', 'procedure', 'A procedure that opens a narrowed leg artery with a balloon and sometimes a stent to improve blood flow. It is used for selected peripheral artery disease cases, especially severe pain or threatened limb.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('mobility-aids', 'Mobility Aids', 'device', 'Canes, crutches, walkers, prostheses, or wheelchairs chosen with a clinician or therapist to improve safety, movement, and daily independence.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('wheelchair-seating', 'Wheelchair Seating and Pressure Care', 'device', 'A properly fitted wheelchair, cushion, positioning plan, and skin-care routine to improve comfort and reduce pressure injury risk.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('assistive-technology', 'Assistive Technology', 'device', 'Tools such as communication devices, adapted keyboards, environmental controls, and reminders that help a person learn, communicate, move, and manage daily tasks.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('hearing-aids', 'Hearing Aids', 'device', 'Devices programmed to make speech and important sounds easier to hear. They work best with careful fitting, follow-up, and communication support.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('audiology-care', 'Audiology Care', 'therapy', 'Hearing assessment, device fitting, listening training, communication planning, and follow-up with an audiologist or hearing specialist.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('cochlear-implant', 'Cochlear Implant', 'device', 'A surgically placed hearing device for selected people with severe hearing loss who do not get enough benefit from hearing aids. It needs assessment, surgery, programming, and listening therapy.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('low-vision-aids', 'Low-Vision Aids', 'device', 'Magnifiers, high-contrast tools, screen readers, lighting changes, and large-print or audio tools that help people use remaining vision.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('vision-rehabilitation', 'Vision Rehabilitation', 'therapy', 'Training and support that helps people adapt to vision loss, use assistive tools, move safely, read, cook, work, study, and manage daily routines.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('orientation-mobility-training', 'Orientation and Mobility Training', 'therapy', 'Training that helps a person with low vision or blindness travel safely using routes, sensory cues, a white cane, or other mobility tools.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('orthotics', 'Orthotics and Bracing', 'device', 'Braces and splints that support joints, guide limb position, reduce pain, and improve comfort or walking stability.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('spasticity-treatment', 'Spasticity Treatment', 'therapy', 'Stretching, positioning, medicines, botulinum toxin injections, or pump therapy used to relax tight muscles and make care or movement easier.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('prosthetic-rehabilitation', 'Prosthetic Rehabilitation', 'therapy', 'Residual-limb care, prosthesis fitting, strengthening, gait training, and daily activity practice after limb loss. It helps the prosthesis feel safer and more useful.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('developmental-therapy-support', 'Developmental Therapy Support', 'therapy', 'Early and ongoing therapy for learning, movement, communication, behaviour, and daily living skills. The plan is matched to the child or adult and their support network.', (unixepoch() * 1000), (unixepoch() * 1000));
INSERT OR IGNORE INTO treatments (slug, name, kind, description, created_at, updated_at) VALUES ('inclusive-education-support', 'Inclusive Education Support', 'therapy', 'School or learning support such as adjusted teaching, extra time, visual schedules, communication tools, and skill-building plans.', (unixepoch() * 1000), (unixepoch() * 1000));

